import time
from typing import Dict, Tuple

class PeerMetricsRegistry:
    """Tracks rolling round-trip times (RTT) and message delivery success/failure for P2P peers."""
    def __init__(self, ttl_seconds: float = 300.0, alpha: float = 0.2):
        self.ttl_seconds = ttl_seconds
        self.alpha = alpha
        self._metrics: Dict[str, Dict[str, float]] = {}

    def record_rtt(self, peer_id: str, rtt: float) -> None:
        now = time.time()
        if peer_id not in self._metrics:
            self._metrics[peer_id] = {
                "rtt": rtt,
                "smoothed_rtt": rtt,
                "failures": 0.0,
                "last_updated": now,
            }
        else:
            m = self._metrics[peer_id]
            m["rtt"] = rtt
            m["smoothed_rtt"] = self.alpha * rtt + (1 - self.alpha) * m["smoothed_rtt"]
            m["last_updated"] = now

    def record_failure(self, peer_id: str) -> None:
        now = time.time()
        if peer_id not in self._metrics:
            self._metrics[peer_id] = {
                "rtt": 1.0,
                "smoothed_rtt": 1.0,
                "failures": 1.0,
                "last_updated": now,
            }
        else:
            self._metrics[peer_id]["failures"] += 1.0
            self._metrics[peer_id]["last_updated"] = now

    def get_metrics(self, peer_id: str) -> Tuple[float, float]:
        self.expire_stale()
        m = self._metrics.get(peer_id)
        if not m:
            return (0.1, 0.0)
        return (m["smoothed_rtt"], m["failures"])

    def expire_stale(self) -> None:
        now = time.time()
        stale_keys = [
            pid for pid, data in self._metrics.items()
            if now - data["last_updated"] > self.ttl_seconds
        ]
        for pid in stale_keys:
            del self._metrics[pid]

import random
from typing import List, Dict, Any
from gossipmesh.p2p.metrics import PeerMetricsRegistry

class AdaptiveTransport:
    """Handles adaptive P2P gossip fanout and peer pruning based on latency metrics."""
    def __init__(self, metrics_registry: PeerMetricsRegistry, base_fanout: int = 4):
        self.metrics_registry = metrics_registry
        self.base_fanout = base_fanout

    def calculate_fanout(self, peer_count: int, congestion_signal: float = 0.0) -> int:
        """Calculates dynamic fanout based on total peers and global congestion."""
        if peer_count <= 0:
            return 1
        effective_fanout = int(self.base_fanout * (1.0 - min(max(congestion_signal, 0.0), 1.0)))
        return max(1, min(effective_fanout, peer_count))

    def select_peers(self, all_peers: List[str], congestion_signal: float = 0.0) -> List[str]:
        """Selects subset of peers to propagate gossip messages to using latency-aware scoring."""
        if not all_peers:
            return []

        fanout = self.calculate_fanout(len(all_peers), congestion_signal)
        if fanout >= len(all_peers):
            return list(all_peers)

        scored_peers = []
        for peer in all_peers:
            smoothed_rtt, failures = self.metrics_registry.get_metrics(peer)
            # Score formula: lower RTT and fewer failures are preferred. Add epsilon to avoid division by zero.
            score = (smoothed_rtt * (1.0 + failures * 2.0))
            scored_peers.append((score, peer))

        scored_peers.sort(key=lambda x: x[0])
        selected = [peer for _, peer in scored_peers[:fanout]]
        return selected
